def _sample_tensor_fingerprint(tensor: torch.Tensor, *, points: int = 17) -> list[float]:
    flat = tensor.detach().reshape(-1)
    if flat.numel() == 0:
        return []
    count = min(points, flat.numel())
    if count == 1:
        indices = torch.zeros(1, dtype=torch.long, device=flat.device)
    else:
        indices = torch.arange(count, dtype=torch.long, device=flat.device)
        indices = indices * (flat.numel() - 1) // (count - 1)
    # vLLM rollout weights are bf16 in the OpenOPD recipes.  Round the actor
    # source through bf16 so a fp32 actor does not create false mismatches.
    return flat[indices].to(dtype=torch.bfloat16).float().cpu().tolist()


